const CLR_TOKENS_CSS = "/* Cognitive Load Router — generated from tokens.json */\n:host, [data-theme=\"dark\"] {\n  --bg: #0c0e1a; /* Page background behind everything: app shell, sidebar gutter, blocked-tab overlay. */\n  --surface: #141729; /* Cards, sidebar, tab bar and top bars. The default ground for text. */\n  --surface-raised: #1b1f35; /* Toasts, menus, bottom sheets, popovers and the mini-player: anything floating above a card. Pair with a shadow token. */\n  --surface-sunken: #090b14; /* Gauge and progress tracks, segmented-control wells, code and pairing-code boxes. Never put body text on it at less than 13px. */\n  --surface-hover: #20243c; /* Hover and pressed fill for rows, ghost buttons and nav items. */\n  --line: #252a42; /* Hairline dividers and card borders (1px). Decorative only: never the only edge of a control. */\n  --line-strong: #646b8e; /* Control borders that must be seen: inputs, unchecked checkboxes, toggle tracks when off, secondary buttons in light mode. At least 3:1 on bg and surface in both themes. */\n  --ink: #eef0f8; /* Primary text and icons on bg, surface and surface-raised. */\n  --ink-muted: #a6acc6; /* Secondary text: explanations, reasons on directive cards, helper text. On bg, surface and surface-raised. */\n  --ink-subtle: #8c93b0; /* Tertiary text: timestamps, axis ticks, captions, inactive tab labels. Still 4.5:1 on bg, surface, surface-raised and surface-sunken. */\n  --ink-inverse: #171a2b; /* Text on surface-inverse (chart tooltips, the VS Code hover). */\n  --surface-inverse: #eef0f8; /* Chart tooltips only. A small, high-contrast flag that floats over data. */\n  --accent: #8f90ff; /* Brand periwinkle. Primary buttons, active nav, links, the selected task outline, focus-mode progress. As text on bg, surface and accent-soft. */\n  --accent-hover: #a6a7ff; /* Hover and pressed fill for primary buttons. */\n  --accent-soft: #23264a; /* Tinted ground behind accent icons and text: active nav item, directive icon tiles, the recommended task row. */\n  --on-accent: #0c0e1a; /* Label and icon colour on an accent fill. Dark ink in dark mode, white in light mode: never hard-code white. */\n  --focus-ring: #b4b5ff; /* The 2px keyboard focus outline, offset 2px. Solid, at least 3:1 on every surface it lands on. */\n  --ctx-deep-focus: #5ed7b5; /* Deep focus: identity colour for the gauge arc, context icon and pill label. Text-safe (4.5:1) on surface, surface-raised and ctx-deep-focus-soft. */\n  --ctx-deep-focus-chart: #009b7a; /* Deep focus as a chart series: timeline segments, stacked bars, the context distribution bar. Validated as one categorical set (CVD-safe in fixed order: deep focus, shallow work, stuck, fatigue, recovering). Place series on surface, never on surface-sunken (light shallow-work falls to 2.6:1 there). Never text. */\n  --ctx-deep-focus-soft: #092d24; /* Deep focus tinted ground: pill background, toast icon disc, filter chip when selected. */\n  --ctx-shallow-work: #e6cd6d; /* Shallow work: identity colour for the gauge arc, context icon and pill label. Text-safe (4.5:1) on surface, surface-raised and ctx-shallow-work-soft. */\n  --ctx-shallow-work-chart: #ae931d; /* Shallow work as a chart series: timeline segments, stacked bars, the context distribution bar. Validated as one categorical set (CVD-safe in fixed order: deep focus, shallow work, stuck, fatigue, recovering). Place series on surface, never on surface-sunken (light shallow-work falls to 2.6:1 there). Never text. */\n  --ctx-shallow-work-soft: #2d2609; /* Shallow work tinted ground: pill background, toast icon disc, filter chip when selected. */\n  --ctx-stuck: #f8a372; /* Stuck: identity colour for the gauge arc, context icon and pill label. Text-safe (4.5:1) on surface, surface-raised and ctx-stuck-soft. */\n  --ctx-stuck-chart: #b2511e; /* Stuck as a chart series: timeline segments, stacked bars, the context distribution bar. Validated as one categorical set (CVD-safe in fixed order: deep focus, shallow work, stuck, fatigue, recovering). Place series on surface, never on surface-sunken (light shallow-work falls to 2.6:1 there). Never text. */\n  --ctx-stuck-soft: #3a1e0e; /* Stuck tinted ground: pill background, toast icon disc, filter chip when selected. */\n  --ctx-fatigue: #efa3c7; /* Fatigue: identity colour for the gauge arc, context icon and pill label. Text-safe (4.5:1) on surface, surface-raised and ctx-fatigue-soft. */\n  --ctx-fatigue-chart: #c66897; /* Fatigue as a chart series: timeline segments, stacked bars, the context distribution bar. Validated as one categorical set (CVD-safe in fixed order: deep focus, shallow work, stuck, fatigue, recovering). Place series on surface, never on surface-sunken (light shallow-work falls to 2.6:1 there). Never text. */\n  --ctx-fatigue-soft: #381c2a; /* Fatigue tinted ground: pill background, toast icon disc, filter chip when selected. */\n  --ctx-recovering: #85c7f1; /* Recovering: identity colour for the gauge arc, context icon and pill label. Text-safe (4.5:1) on surface, surface-raised and ctx-recovering-soft. */\n  --ctx-recovering-chart: #4498ca; /* Recovering as a chart series: timeline segments, stacked bars, the context distribution bar. Validated as one categorical set (CVD-safe in fixed order: deep focus, shallow work, stuck, fatigue, recovering). Place series on surface, never on surface-sunken (light shallow-work falls to 2.6:1 there). Never text. */\n  --ctx-recovering-soft: #0e293a; /* Recovering tinted ground: pill background, toast icon disc, filter chip when selected. */\n  --ctx-unknown: #b2b7c5; /* Warming up: identity colour for the gauge arc, context icon and pill label. Text-safe (4.5:1) on surface, surface-raised and ctx-unknown-soft. */\n  --ctx-unknown-chart: #7b808d; /* Warming up as a chart series: timeline segments, stacked bars, the context distribution bar. Validated as one categorical set (CVD-safe in fixed order: deep focus, shallow work, stuck, fatigue, recovering). Place series on surface, never on surface-sunken (light shallow-work falls to 2.6:1 there). Never text. */\n  --ctx-unknown-soft: #21242b; /* Warming up tinted ground: pill background, toast icon disc, filter chip when selected. */\n  --load-intrinsic: #8c7dd5; /* Intrinsic load (task difficulty) bar and series. A chart colour, never text. */\n  --load-extraneous: #bd853f; /* Extraneous load (distraction and switching) bar and series. A chart colour, never text. */\n  --load-germane: #209993; /* Germane load (productive effort) bar and series. A chart colour, never text. */\n  --positive: #5fd3a8; /* Live connection, connected sources, success confirmations. Always with a word or icon. Text-safe on surface and positive-soft. */\n  --positive-soft: #0b2a22; /* Ground behind positive text and the Live badge. */\n  --caution: #e8c35a; /* Reconnecting, low confidence notices, unsaved changes. Text-safe on surface and caution-soft. */\n  --caution-soft: #2f2610; /* Ground for caution banners. */\n  --critical: #ff8f85; /* Destructive actions (delete my data) and form errors only. Never for load, fatigue or stuck. Text-safe on surface and critical-soft. */\n  --critical-soft: #3a1714; /* Ground for error banners and the danger zone in Settings. */\n  --on-critical: #1a0b0a; /* Label on a critical fill (the danger button). */\n  --rest-surface: #0f1c26; /* Break screens: the whole canvas turns to this calm ground so a break never looks like work. */\n  --rest-surface-raised: #142735; /* Cards and the breathing disc on a break screen. */\n  --rest-line: #1e3545; /* Hairlines and the timer track on a break screen. */\n  --rest-ink: #e6f2f8; /* Primary text on rest-surface and rest-surface-raised. */\n  --rest-ink-muted: #9fbccb; /* Secondary text on rest-surface. */\n  --rest-accent: #7cc7ee; /* Break timer arc, break buttons and icons on rest-surface. Text-safe there. */\n  --chart-grid: #20243a; /* Chart gridlines (1px). Recessive by design. */\n  --chart-threshold: #646b8e; /* Dashed reference lines for the high-load and fatigue thresholds, and the gauge threshold ticks. */\n  --heat-0: #1c1e2d; /* Heatmap: no focus that hour. */\n  --heat-1: #31335b; /* Heatmap: a little focus (under 10 min). */\n  --heat-2: #4d4f94; /* Heatmap: some focus (10 to 25 min). */\n  --heat-3: #7174d1; /* Heatmap: solid focus (25 to 45 min). */\n  --heat-4: #a2a8fc; /* Heatmap: your best hours (45 min or more). */\n  --skeleton: #1c2036; /* Skeleton block fill while data loads. */\n  --skeleton-shine: #262b46; /* The moving highlight on a skeleton (static when reduced motion is on). */\n  --scrim: rgba(5, 6, 12, 0.64); /* Behind bottom sheets, dialogs and the blocked-tab card. Solid colour, no backdrop blur (WebView performance). */\n  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.4); /* Selected segmented option, slider thumb, toggle thumb. */\n  --shadow-md: 0 8px 24px rgba(0, 0, 0, 0.45); /* Toasts, menus, the mini-player. */\n  --shadow-lg: 0 20px 56px rgba(0, 0, 0, 0.55); /* Bottom sheets, dialogs, the blocked-tab card. */\n}\n[data-theme=\"light\"] {\n  --bg: #f5f4f0;\n  --surface: #ffffff;\n  --surface-raised: #ffffff;\n  --surface-sunken: #eceae4;\n  --surface-hover: #f0efea;\n  --line: #e2e0d9;\n  --line-strong: #7f8496;\n  --ink: #171a2b;\n  --ink-muted: #4f546a;\n  --ink-subtle: #5f6479;\n  --ink-inverse: #f5f4f0;\n  --surface-inverse: #1f2233;\n  --accent: #4b4bd6;\n  --accent-hover: #3c3cc0;\n  --accent-soft: #ebebfd;\n  --on-accent: #ffffff;\n  --focus-ring: #4b4bd6;\n  --ctx-deep-focus: #00664f;\n  --ctx-deep-focus-chart: #008767;\n  --ctx-deep-focus-soft: #ddf7ee;\n  --ctx-shallow-work: #715700;\n  --ctx-shallow-work-chart: #b18e15;\n  --ctx-shallow-work-soft: #f8f0d6;\n  --ctx-stuck: #923e00;\n  --ctx-stuck-chart: #b14c00;\n  --ctx-stuck-soft: #ffebdf;\n  --ctx-fatigue: #7c3367;\n  --ctx-fatigue-chart: #953d7c;\n  --ctx-fatigue-soft: #ffe9f7;\n  --ctx-recovering: #006192;\n  --ctx-recovering-chart: #197cb3;\n  --ctx-recovering-soft: #e2f3ff;\n  --ctx-unknown: #565b66;\n  --ctx-unknown-chart: #757a87;\n  --ctx-unknown-soft: #eef0f4;\n  --load-intrinsic: #654db6;\n  --load-extraneous: #ad721c;\n  --load-germane: #008b77;\n  --positive: #0f7a55;\n  --positive-soft: #e1f5ec;\n  --caution: #845f00;\n  --caution-soft: #fbf1d9;\n  --critical: #c2352b;\n  --critical-soft: #fdeceb;\n  --on-critical: #ffffff;\n  --rest-surface: #e8f2f6;\n  --rest-surface-raised: #f4f9fb;\n  --rest-line: #c9dde6;\n  --rest-ink: #10283a;\n  --rest-ink-muted: #3f5c6e;\n  --rest-accent: #1e6a9e;\n  --chart-grid: #ebe9e3;\n  --chart-threshold: #7f8496;\n  --heat-0: #ebedfc;\n  --heat-1: #c9cdf9;\n  --heat-2: #9ea4e9;\n  --heat-3: #7173d7;\n  --heat-4: #4a41b8;\n  --skeleton: #eceae4;\n  --skeleton-shine: #f6f5f1;\n  --scrim: rgba(23, 26, 43, 0.4);\n  --shadow-sm: 0 1px 2px rgba(23, 26, 43, 0.08);\n  --shadow-md: 0 6px 20px rgba(23, 26, 43, 0.1);\n  --shadow-lg: 0 18px 48px rgba(23, 26, 43, 0.16);\n}\n:host {\n  --space-1: 4px; /* Icon-to-label gap inside chips and pills. */\n  --space-2: 8px; /* Gap between an icon and its text; between stacked label and value. */\n  --space-3: 12px; /* Gap between list rows and between chips. */\n  --space-4: 16px; /* Card padding on mobile; mobile page gutter; gap between cards on mobile. */\n  --space-5: 20px; /* Card padding on desktop. */\n  --space-6: 24px; /* Grid gutter on desktop and tablet; gap between cards. */\n  --space-8: 32px; /* Desktop page padding (top and sides); space between page sections. */\n  --space-10: 40px; /* Space above a page title; onboarding step padding. */\n  --space-12: 48px; /* Empty-state vertical padding. */\n  --space-16: 64px; /* Auth and onboarding panel padding on desktop. */\n  --radius-xs: 6px; /* Chips, tags, heatmap cells, small badges. */\n  --radius-sm: 8px; /* Inputs inside dense tables, segmented-control options, tooltip. */\n  --radius-md: 12px; /* Buttons, inputs, directive icon tiles, task rows. */\n  --radius-lg: 16px; /* Cards, toasts, the mini-player. */\n  --radius-xl: 24px; /* Bottom-sheet top corners, the extension popup, the blocked-tab card. */\n  --radius-full: 999px; /* Pills, toggles, avatars, the play button, status dots. */\n  --dur-instant: 80ms; /* Press feedback, toggle thumb colour. */\n  --dur-fast: 140ms; /* Hover fills, focus ring, chip selection. */\n  --dur-base: 240ms; /* Toasts in and out, sheet content fade, banner swap. */\n  --dur-slow: 400ms; /* Context colour crossfade, task reorder (FLIP), sheet slide. */\n  --dur-gauge: 600ms; /* Gauge arc and number tween. Shorter than the 2s update interval, so each tick settles before the next. */\n  --dur-breath: 8000ms; /* One full breathing cycle on break screens (4s in, 4s out). */\n  --ease-standard: cubic-bezier(0.2, 0, 0, 1); /* Most UI transitions. */\n  --ease-out: cubic-bezier(0.16, 1, 0.3, 1); /* Gauge, number tweens and entering elements: fast start, soft landing. */\n  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1); /* Breathing disc and reorder moves. */\n  --sidebar-width: 248px; /* Desktop sidebar (1024px and up). Collapses to a 72px icon rail at 1024 to 1279px. */\n  --rail-width: 72px; /* Icon-only sidebar on small desktops and tablets in landscape. */\n  --topbar-height: 72px; /* Desktop top bar. */\n  --mobile-topbar-height: 56px; /* Mobile top bar under the Android status bar. */\n  --tabbar-height: 64px; /* Mobile bottom tab bar, plus env(safe-area-inset-bottom). */\n  --miniplayer-height: 56px; /* Persistent timer bar, docked 8px above the tab bar on mobile. */\n  --touch-target: 44px; /* Minimum hit area for anything tappable, even when the visual is smaller. */\n  --content-max: 1200px; /* Max width of the main column on wide screens. */\n  --z-sticky: 10; /* Sticky table headers and the mobile top bar. */\n  --z-nav: 20; /* Sidebar and tab bar. */\n  --z-miniplayer: 30; /* The persistent timer bar. */\n  --z-sheet: 40; /* Bottom sheets, dialogs and their scrim. */\n  --z-toast: 50; /* Toasts, always above sheets. */\n  --font-sans: \"Geist\", system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  --font-mono: \"Geist Mono\", ui-monospace, \"SF Mono\", Menlo, monospace;\n  --text-num-gauge: 600 72px/72px var(--font-sans); /* The load number inside the hero gauge (desktop 280px gauge). 56px on mobile. Always tabular numerals. */\n  --text-num-timer: 500 64px/64px var(--font-sans); /* Pomodoro and focus countdown. 56px on mobile. Tabular numerals so digits never shift. */\n  --text-num-stat: 600 28px/34px var(--font-sans); /* Stat tiles and KPI values. */\n  --text-num-inline: 500 15px/20px var(--font-sans); /* Percentages in breakdown rows, durations in task rows, playback time. */\n  --text-title-1: 600 28px/34px var(--font-sans); /* Page title in the desktop top bar; auth and onboarding headings. */\n  --text-title-2: 600 20px/28px var(--font-sans); /* Mobile top-bar title, hero context name, sheet titles. */\n  --text-title-3: 600 16px/24px var(--font-sans); /* Card titles, empty-state titles, toast titles. */\n  --text-body-lg: 400 17px/26px var(--font-sans); /* Hero explanations, onboarding copy, break-screen prompts. */\n  --text-body: 400 15px/22px var(--font-sans); /* Default UI text. 16px minimum inside inputs on mobile (prevents zoom). */\n  --text-body-sm: 400 13px/20px var(--font-sans); /* Reasons, helper text, breakdown explanations, table cells. */\n  --text-label: 500 14px/20px var(--font-sans); /* Buttons, nav items, field labels, chips. */\n  --text-caption: 500 12px/16px var(--font-sans); /* Timestamps, axis ticks, tab-bar labels (12px is the floor). */\n  --text-overline: 600 11px/16px var(--font-sans); /* Section eyebrows above card groups. Set text-transform: uppercase in CSS; never use for sentences. */\n  --text-code: 500 20px/28px var(--font-mono); /* Pairing codes on source cards and the VS Code status-bar text spec. */\n}\n.num-gauge {\n  font-family: var(--font-sans);\n  font-size: 72px;\n  line-height: 72px;\n  font-weight: 600;\n  letter-spacing: -0.04em;\n}\n.num-timer {\n  font-family: var(--font-sans);\n  font-size: 64px;\n  line-height: 64px;\n  font-weight: 500;\n  letter-spacing: -0.03em;\n}\n.num-stat {\n  font-family: var(--font-sans);\n  font-size: 28px;\n  line-height: 34px;\n  font-weight: 600;\n  letter-spacing: -0.02em;\n}\n.num-inline {\n  font-family: var(--font-sans);\n  font-size: 15px;\n  line-height: 20px;\n  font-weight: 500;\n  letter-spacing: 0;\n}\n.title-1 {\n  font-family: var(--font-sans);\n  font-size: 28px;\n  line-height: 34px;\n  font-weight: 600;\n  letter-spacing: -0.02em;\n}\n.title-2 {\n  font-family: var(--font-sans);\n  font-size: 20px;\n  line-height: 28px;\n  font-weight: 600;\n  letter-spacing: -0.01em;\n}\n.title-3 {\n  font-family: var(--font-sans);\n  font-size: 16px;\n  line-height: 24px;\n  font-weight: 600;\n  letter-spacing: 0;\n}\n.body-lg {\n  font-family: var(--font-sans);\n  font-size: 17px;\n  line-height: 26px;\n  font-weight: 400;\n  letter-spacing: 0;\n}\n.body {\n  font-family: var(--font-sans);\n  font-size: 15px;\n  line-height: 22px;\n  font-weight: 400;\n  letter-spacing: 0;\n}\n.body-sm {\n  font-family: var(--font-sans);\n  font-size: 13px;\n  line-height: 20px;\n  font-weight: 400;\n  letter-spacing: 0;\n}\n.label {\n  font-family: var(--font-sans);\n  font-size: 14px;\n  line-height: 20px;\n  font-weight: 500;\n  letter-spacing: 0;\n}\n.caption {\n  font-family: var(--font-sans);\n  font-size: 12px;\n  line-height: 16px;\n  font-weight: 500;\n  letter-spacing: 0;\n}\n.overline {\n  font-family: var(--font-sans);\n  font-size: 11px;\n  line-height: 16px;\n  font-weight: 600;\n  letter-spacing: 0.08em;\n}\n.code {\n  font-family: var(--font-mono);\n  font-size: 20px;\n  line-height: 28px;\n  font-weight: 500;\n  letter-spacing: 0.12em;\n}";
